const $ = (s, r=document) => r.querySelector(s);
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4z M13 7a3 3 0 0 1 3-3h5v15h-4a4 4 0 0 0-4 2',home:'M3 10l9-7 9 7v10h-6v-6H9v6H3z',people:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M17 4a4 4 0 0 1 0 7 M18 14a4 4 0 0 1 4 4v3',theme:'M12 3v18 M3 12h18 M5.6 5.6l12.8 12.8 M5.6 18.4L18.4 5.6',pen:'M4 20l4-1 12-12-3-3L5 16z M14 7l3 3',quote:'M4 6h6v7H5v4H3v-6z M15 6h6v7h-5v4h-2v-6z',cards:'M6 3h14v16H6z M3 7v15h13',quiz:'M9 5H4v16h16V5h-5 M9 3h6v4H9z M8 12l2 2 6-5',check:'M5 12l4 4L19 6',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',arrow:'M4 12h16 M14 6l6 6-6 6',left:'M20 12H4 M10 6l-6 6 6 6',source:'M8 7H4v14h14v-4 M12 3h9v9 M21 3L10 14',menu:'M4 6h16 M4 12h16 M4 18h16',close:'M5 5l14 14 M19 5L5 19',leaf:'M4 21c0-9 7-13 15-17 1 11-3 16-10 16 M4 21l10-10'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;
const link=(href,text,cls='text-link')=>`<a class="${cls}" href="#${href}">${text}${icon('arrow')}</a>`;
const list=a=>`<ul>${(a||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
const chips=a=>(a||[]).map(x=>`<span class="chip">${esc(x)}</span>`).join('');
const KEY='nlmg-revision-room-v1';let state={chapters:[],checks:[],known:[],notes:{},essays:{},zh:true,best:0,language:'bilingual',part1Session:null,part1Best:0};let storageOK=true;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&typeof saved==='object')state={...state,...saved};}catch{storageOK=false;}
if(!['bilingual','chinese','english'].includes(state.language))state.language='bilingual';
state.zh=state.language!=='english';
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}}
function toast(text){$('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),2800);}
const words=(en,cn)=>state.zh&&cn?cn:en;
const bi=(en,cn,tag='p')=>`${state.language!=='chinese'||!cn?`<${tag} class="en-copy">${esc(en)}</${tag}>`:''}${state.zh&&cn?`<${tag} class="zh-copy" lang="zh-CN">${esc(cn)}</${tag}>`:''}`;
const dualTitle=(en,cn)=>`${esc(en)}${state.zh&&cn?`<span class="title-zh" lang="zh-CN">${esc(cn)}</span>`:''}`;
const zh=x=>state.zh&&x?`<p class="zh" lang="zh-CN">${esc(x)}</p>`:'';
const button=(action,text,cls='btn',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const intro=(tag,title,desc)=>`<div class="page-intro"><div class="eyebrow">${tag}</div><h1>${title}</h1><p>${desc}</p></div>`;
let data, chapterFilter=0,flashFilter='All',flashIndex=0,flashFlipped=false,flashOrder=[],quizIndex=0,quizAnswers=[],quizDone=false,essayId=null;
const nav=[['overview','home','Overview',''],['chapters','book','Chapter guide','23'],['characters','people','Characters',''],['themes','theme','Themes & ideas',''],['methods','pen','Writer’s craft',''],['evidence','quote','Evidence bank',''],['flashcards','cards','Flashcards',''],['part1-revision','book','Quiz revision notes',''],['part1-quiz','quiz','Chapters 1–9 quiz','60'],['quiz','quiz','Whole-novel quiz','20'],['essays','pen','Essay workshop',''],['progress','check','My revision',''],['sources','source','Context & sources','']];
const navZh={overview:'学习首页',chapters:'逐章精读',characters:'人物解读',themes:'主题与思想',methods:'写作手法',evidence:'证据库',flashcards:'记忆卡片','part1-revision':'考前速记','part1-quiz':'第1–9章专项',quiz:'全书测验',essays:'写作练习',progress:'我的进度',sources:'背景与参考'};
const partNames=['','Hailsham','The Cottages','Carers & donors'];
function landscape(){return `<svg viewBox="0 0 650 440" preserveAspectRatio="xMidYMid slice" role="img" aria-label="An original illustration of a quiet English landscape and an empty boat"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#e3e7d8"/><stop offset="1" stop-color="#c5cfb9"/></linearGradient><linearGradient id="field" x2="0" y2="1"><stop stop-color="#a4b298"/><stop offset="1" stop-color="#546e54"/></linearGradient><filter id="grain"><feTurbulence type="fractalNoise" baseFrequency=".7" numOctaves="3" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".09"/></feComponentTransfer><feBlend in="SourceGraphic" mode="multiply"/></filter></defs><g filter="url(#grain)"><rect width="650" height="440" fill="url(#sky)"/><circle cx="408" cy="110" r="47" fill="#eeeede" opacity=".6"/><path d="M0 240Q100 195 210 220T430 205T650 185V440H0Z" fill="#abbba0"/><path d="M0 283Q140 240 250 266T480 242T650 257V440H0Z" fill="url(#field)"/><path d="M460 440Q340 330 405 280T400 233Q372 280 318 300T288 440" fill="#bfccb7"/><path d="M0 370Q150 312 299 353L260 440H0z" fill="#7e9471"/><path d="M455 330l86-8-22 22-41 2z" fill="#3f5847"/><path d="M455 330l63 5 23-13-63-2z" fill="#9da88b"/><path d="M0 325q100-12 210 6 M440 365q100-12 210 8 M460 390q90-5 190 6" fill="none" stroke="#d0d8be" opacity=".35"/><g fill="#687f61"><path d="M545 231l3-113 5 113z"/><path d="M548 129c-66-24-45-63-17-60-17-31 27-48 38-20 43-7 56 30 29 47 28 29 1 55-50 33z"/><path d="M589 243l3-74 4 74z"/><path d="M593 182c-35-4-49-35-17-45-10-31 35-37 39-11 40 10 23 51-22 56z"/></g><g stroke="#667f5c" stroke-width="2"><path d="M105 439l-9-54m9 39 12-29m-17 3-16-15 M150 440l2-42m-1 29 14-17 M559 440l-9-49m7 31 16-24 M604 440l2-67m0 30 13-16"/></g><path d="M343 130q5-7 11 0m5-5q5-7 11 0" stroke="#6c8067" fill="none"/></g></svg>`;}
function footer(){const part1=location.hash.startsWith('#part1-');return `<footer class="footer"><span>${part1?words('This section: Chapters 1–9 only. Other sections discuss the whole novel.','本专区仅涉及第1–9章；其他栏目可能涉及全书情节。'):words('An independent companion to Kazuo Ishiguro’s novel · Full-novel spoilers','独立文学学习指南 · 全书内容与结局讨论')}</span><a href="#sources">Original study notes · Sources & reading guidance ↗</a></footer>`;}
function shell(){const rawSection=(location.hash.slice(1).split('/')[0]||'overview');const section=rawSection;const current=nav.find(n=>n[0]===section)||nav[0];const n=state.chapters.length;$('#app').innerHTML=`<aside class="sidebar" id="sidebar"><a class="brand" href="#overview"><span class="brand-mark">${icon('book')}</span><span>The Revision Room<small>A literary companion</small></span></a><button class="mobile-close" data-action="menu" aria-label="Close navigation">${icon('close')}</button><nav aria-label="Main navigation">${nav.map((x,i)=>`${i===0?'<div class="nav-label">Your bookshelf</div>':''}${i===6?'<div class="nav-label">Active revision</div>':''}${x[0]==='sources'?'<div class="nav-label">Reference</div>':''}<a class="nav-link ${section===x[0]?'active':''}" href="#${x[0]}" ${section===x[0]?'aria-current="page"':''}>${icon(x[1])}<span class="nav-text">${x[2]}${state.zh?`<small>${navZh[x[0]]||''}</small>`:''}</span>${x[3]?`<span class="count">${x[3]}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="progress-label"><span>Chapter revision</span><span>${n} / 23</span></div><div class="progress-track"><span style="width:${n/23*100}%"></span></div><div class="sidebar-foot">KAZUO ISHIGURO<br>Never Let Me Go · 2005<br>All three parts. One place to revise.</div></div></aside><div class="workspace"><header class="topbar"><button class="menu-button" data-action="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><div class="crumb">Literature <span aria-hidden="true">/</span> <b>${current[2]}</b></div><div class="top-actions"><button class="search-button" data-action="search" aria-label="Search the study guide">${icon('search')}<span>Find an idea, scene, character</span><kbd>/</kbd></button><label class="language-label"><span class="sr-only">Study language / 学习语言</span><select id="language-select" aria-label="Study language / 学习语言"><option value="bilingual" ${state.language==='bilingual'?'selected':''}>中英双语</option><option value="chinese" ${state.language==='chinese'?'selected':''}>中文为主</option><option value="english" ${state.language==='english'?'selected':''}>English</option></select></label></div></header><main class="main" id="main" tabindex="-1"></main></div><dialog id="search-dialog" aria-label="Search the study guide"><div class="search-head">${icon('search')}<input id="search-input" placeholder="Search the whole study guide…" aria-label="Search"><button data-action="close-search" aria-label="Close search">${icon('close')}</button></div><div class="search-results"><p class="small-note">Try memory, Madame, art, or deferrals.</p></div></dialog>`;renderPage();}
function overview(){let next=data.chapters.find(c=>!state.chapters.includes(c.id))||data.chapters[0];return `<section class="hero"><div class="hero-copy"><div class="eyebrow">Kazuo Ishiguro · The complete study companion</div><h1>Never<br>Let Me Go<span style="color:#7b8c6a">.</span></h1><p>A story of memory, love, and what makes us human. Read closely. Make connections. Find your own argument.</p><div class="hero-actions">${link('chapters/'+next.id,state.chapters.length?'Continue revising':'Begin with Chapter 1','btn')}${link('part1-quiz',words('Practise Chapters 1–9','第1–9章专项练习'))}</div></div><div class="hero-art">${landscape()}</div></section><section class="focus-banner"><div><div class="eyebrow">QUIZ PREP · CHAPTERS 1–9</div><h2>${words('A clear revision sheet before your quiz.','考前速记：年份、人名、容易漏掉的细节。')}</h2><p>${words('Publication facts, guardians, minor students and detail traps, with Chinese explanations. Read the notes, then try the 60-question quiz.','先用中英复习笔记记准出版年份、guardians、学生名字与易错细节，再做60道第一部专项题。')}</p></div><div class="banner-links">${link('part1-revision',words('Read the revision notes','打开考前复习笔记'),'btn')}${link('part1-quiz',words('Start the Chapter 1–9 quiz','开始第1–9章测验'))}</div></section><div class="stats"><div class="stat"><strong>23</strong><span>chapters<br>explained</span></div><div class="stat"><strong>${data.themes.length}</strong><span>connected<br>themes</span></div><div class="stat"><strong>${data.flashcards.length}</strong><span>active-recall<br>flashcards</span></div><div class="stat"><strong>${data.essays.length}</strong><span>essay<br>workshops</span></div></div><section><div class="section-heading"><div><h2>Follow the story</h2><p>Three places. Three stages of a life.</p></div>${link('chapters','Explore all chapters')}</div><div class="grid three">${[{n:1,range:'01–09',desc:'Childhood, friendship, and the truths hidden in plain sight.',route:1},{n:2,range:'10–17',desc:'Borrowed identities, imagined futures, and fragile hopes.',route:10},{n:3,range:'18–23',desc:'Reunion, revelation, and learning to live with loss.',route:18}].map(x=>`<a href="#chapters/${x.route}" class="card link part-card"><div class="card-top"><span class="eyebrow">Part ${['','one','two','three'][x.n]}</span><span class="part-no">0${x.n}</span></div><h3>${partNames[x.n]}</h3><p>${x.desc}</p><div class="card-foot"><span>Chapters ${x.range}</span>${icon('arrow')}</div></a>`).join('')}</div></section><div class="dashboard-bottom"><section class="card"><div class="eyebrow">Make your revision count</div><h2 style="margin-top:10px;font-size:30px">From remembering to analysing.</h2>${[['01','themes','Find the connections','Trace a theme across the whole novel.'],['02','evidence','Build an argument','Move from a detail to its wider meaning.'],['03','essays','Put it into words','Plan, practise, and refine your response.']].map(x=>`<a class="route-item" href="#${x[1]}"><span class="number">${x[0]}</span><div><h4>${x[2]}</h4><p>${x[3]}</p></div>${icon('arrow')}</a>`).join('')}</section><section class="card note-card"><div class="eyebrow">A question worth returning to</div><blockquote>What does it mean to be “told and not told”?</blockquote><p>Knowing a fact is different from understanding what it means for your life. Start here to explore Hailsham’s careful silences.</p><div style="margin-top:22px">${link('chapters/7','Revisit Chapter 7')}</div></section></div><p class="small-note" style="margin-top:25px">Whole-novel coverage, including the ending. Detailed bilingual study notes, with English and Chinese reading modes. Progress and writing stay in this browser.</p>`;}
function chapters(){return intro('Read & understand','The chapter guide.','The whole novel, one chapter at a time: what happens, how it is told, and why it matters.')+`<div class="filters" role="group" aria-label="Filter chapters">${['All chapters','Part 1 · Hailsham','Part 2 · The Cottages','Part 3 · Carers & donors'].map((s,i)=>button('part-filter',s,'filter '+(chapterFilter===i?'active':''),`data-value="${i}" aria-pressed="${chapterFilter===i}"`)).join('')}</div><div class="chapter-list">${data.chapters.filter(c=>!chapterFilter||c.part===chapterFilter).map(c=>`<a href="#chapters/${c.id}" class="card link chapter-card ${state.chapters.includes(c.id)?'done':''}"><div style="display:flex;justify-content:space-between;align-items:center"><span class="chapter-n">${String(c.id).padStart(2,'0')}</span><span class="eyebrow">Part ${c.part}</span></div><h3>${dualTitle(c.title,c.titleZh)}</h3><p>${esc(c.themes.join(' · '))}</p><div class="card-foot"><span>${state.chapters.includes(c.id)?'✓ Revised':'Summary · Analysis · Recall'}</span>${icon('arrow')}</div></a>`).join('')}</div>`;}
function sourceRefs(ids){return `<div class="source-ref">${(ids||[]).map(id=>data.sources.find(x=>x.id===id)).filter(Boolean).map(x=>x.id==='user-epub'?`<span>${words('Checked against your supplied EPUB · Chapter divisions verified','已对照你提供的 EPUB 核对章节与细节')}</span>`:`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)} ↗</a>`).join('')}</div>`;}
function chapter(id){
 const c=data.chapters.find(x=>x.id===Number(id));if(!c)return notFound();const done=state.chapters.includes(c.id);
 const headings=[['summary','Overview','整体梳理'],['scenes','Scene by scene','按场景读懂'],['details','Remember the details','人物与细节'],['analysis','Read beneath the surface','深一层分析'],['recall','Check your understanding','理解自测']];
 return `<a class="back" href="#chapters">${icon('left')} ${words('All chapters','全部章节')}</a>${intro(`Part ${c.part} · ${partNames[c.part]} · Chapter ${c.id}`,dualTitle(c.title,c.titleZh),'')}<div class="detail-layout"><article class="reading chapter-reading"><div class="tag-row">${chips(c.themes)}</div><div class="chapter-orientation">${bi(c.orientation?.en||'',c.orientation?.zh||'')}</div><section id="chapter-summary"><h2>${words('The whole chapter, clearly','先把这一章读清楚')}</h2>${bi(c.summary,c.summaryZh||c.zh)}</section><section id="chapter-scenes"><h2>${words('Follow the scenes','按场景理解：发生了什么，为什么？')}</h2>${(c.scenes||[]).map((x,i)=>`<details class="scene" open><summary><span class="scene-number">0${i+1}</span><span>${dualTitle(x.title,x.titleZh)}</span></summary><div class="scene-body">${bi(x.text,x.zh)}</div></details>`).join('')}</section><section id="chapter-details"><h2>${words('Details worth remembering','容易考、也容易混淆的细节')}</h2><div class="detail-facts">${(c.details||[]).map(x=>`<div class="fact"><h3>${esc(x.label)}</h3>${bi(x.value,x.zh)}</div>`).join('')}</div></section><section id="chapter-analysis"><h2>${words('Read beneath the surface','从情节走向分析')}</h2>${c.analysis.map(a=>`<div class="analysis-box"><h3>${esc(a.method)}</h3>${state.language!=='chinese'?`<span class="label">The detail</span><p>${esc(a.detail)}</p><span class="label">What it suggests</span><p>${esc(a.effect)}</p>`:''}${zh(a.zh)}</div>`).join('')}<div class="callout pitfall"><div class="eyebrow">${words('Avoid this shortcut','别把它理解得太简单')}</div>${bi(c.pitfall?.en||'',c.pitfall?.zh||'')}</div></section><section class="recall" id="chapter-recall"><span class="eyebrow">${words('Pause & retrieve','先自己想，再看解析')}</span>${bi(c.question,c.questionZh,'h3')}${button('reveal',words('Reveal a possible answer','查看参考答案'),'btn secondary small','style="margin-top:15px" aria-expanded="false"')}<div class="answer hidden">${bi(c.answer,c.answerZh)}</div></section>${c.id<=9?`<div class="callout">${bi('Test names, objects, events and interpretations from this chapter.','把人物、物品、情节和含义一起练习。专项测验只涉及第1–9章。')}${link('part1-quiz/'+c.id,words('Practise Chapter '+c.id,'练习第'+c.id+'章'),'btn')}</div>`:''}${sourceRefs(c.sourceIds)}<div class="aside-nav">${c.id>1?link('chapters/'+(c.id-1),words('Previous chapter','上一章'),'btn secondary'):''}${c.id<23?link('chapters/'+(c.id+1),words('Next chapter','下一章'),'btn'):link('quiz',words('Test the whole novel','全书测验'),'btn')}</div></article><aside class="detail-aside"><div class="card chapter-toc"><div class="eyebrow">${words('In this chapter','本章导航')}</div>${headings.map(([id,en,cn])=>button('jump-section',words(en,cn),'toc-link',`data-target="chapter-${id}"`)).join('')}</div><div class="card"><div class="eyebrow">${words('Your reading journey','你的阅读进度')}</div><h3 style="margin-top:12px">Chapter ${c.id} / 23</h3>${button('chapter-done',done?words('✓ Chapter revised','✓ 已复习'):words('Mark as revised','标记为已复习'),done?'btn secondary':'btn',`data-id="${c.id}" aria-pressed="${done}"`)}</div><div class="card"><label for="chapter-note"><h3>${words('My margin notes','我的批注')}</h3></label><textarea id="chapter-note" data-note="chapter-${c.id}" placeholder="${words('A connection, a question, a detail to remember…','记录一个疑问、一个联系，或一个需要记住的细节……')}">${esc(state.notes['chapter-'+c.id]||'')}</textarea><span class="save-label">${storageOK?words('Saved automatically in this browser.','自动保存在当前浏览器。'):words('Export before leaving.','请在离开前导出。')}</span></div>${button('print',words('Print this chapter','打印本章'),'btn secondary small')}</aside></div>`;
}
function collection(section){const config={characters:['People & relationships','The people we remember.','Follow each character’s development, contradictions, and relationships.'],themes:['Ideas & connections','The threads that run through it.','Build an argument by tracing ideas across childhood, adulthood, and the ending.'],methods:['Language, structure & form','How Ishiguro tells the story.','Name the method, examine a specific detail, and explain what that choice allows the reader to see.']};const c=config[section];return intro(...c)+`<div class="grid ${section==='methods'?'two':'three'}">${data[section].map((x,i)=>`<a class="card link term-card" href="#${section}/${x.id}"><div class="card-top">${section==='characters'?`<span class="character-avatar">${esc(x.name[0])}</span>`:`<span class="eyebrow">${section==='themes'?'Theme':'Method'} ${String(i+1).padStart(2,'0')}</span>`}${icon('arrow')}</div><h3>${esc(x.name||x.title)}</h3><p>${esc(x.role||x.thesis||x.explanation)}</p></a>`).join('')}</div>${section==='methods'?`<h2 style="margin:38px 0 20px">Objects, places & recurring images</h2><div class="grid two">${data.symbols.map(x=>`<article class="card"><h3 class="serif">${esc(x.title)}</h3><p>${esc(x.meaning)}</p><div class="analysis-box"><span class="label">In the text</span><p>${esc(x.evidence)}</p></div><p><b>Keep it nuanced:</b> ${esc(x.nuance)}</p></article>`).join('')}</div>`:''}`;}
function chineseGuide(section,id){const paragraphs=data.guides?.[section]?.[id];return state.zh&&paragraphs?`<section class="chinese-guide" lang="zh-CN"><div class="eyebrow">中文精讲 · 保留关键 English terms</div><h3>怎样理解，怎样写进分析？</h3>${paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</section>`:'';}
function analysisDetail(section,id){const x=data[section].find(x=>String(x.id)===id);if(!x)return notFound();let content='';if(section==='characters')content=`<p>${esc(x.overview)}</p>${zh(x.zh)}<h2>A life in the novel</h2>${list(x.arc)}<h2>Relationships</h2>${list(x.relationships)}<h2>Arguments to develop</h2>${list(x.arguments)}<h2>Scenes to return to</h2>${list(x.evidence)}`;if(section==='themes')content=`<div class="callout"><div class="eyebrow">A possible argument</div><p>${esc(x.thesis)}</p></div>${zh(x.zh)}<h2>Across the novel</h2>${list(x.development)}<h2>Evidence to connect</h2>${list(x.evidence)}<h2>How the writing shapes the idea</h2>${list(x.methods)}<div class="callout"><h3>A more nuanced reading</h3><p>${esc(x.nuance)}</p></div><section class="recall"><div class="eyebrow">Try an argument</div><h3>${esc(x.question)}</h3><p class="small-note">Write a claim, choose two scenes, and explain why their differences matter.</p></section>`;if(section==='methods')content=`<p>${esc(x.explanation)}</p><h2>Find it in the text</h2><p>${esc(x.example)}</p><h2>Explain the effect</h2><p>${esc(x.effect)}</p><div class="recall"><div class="eyebrow">Apply it yourself</div><h3>${esc(x.question)}</h3></div>`;return `<a class="back" href="#${section}">${icon('left')} Back to ${section==='methods'?'writer’s craft':section}</a>${intro(section==='characters'?'Character study':section==='themes'?'Theme study':'Close reading',esc(x.name||x.title),esc(x.role||''))}<div class="detail-layout"><article class="reading">${chineseGuide(section,id)}${content}${sourceRefs(x.sourceIds)}</article><aside class="detail-aside"><div class="card"><h3>Make the connection</h3><p>Turn this reading into a paragraph: detail → implication → wider argument.</p>${link('essays','Open essay workshop','btn')}</div><div class="card"><label class="field-label" style="margin-top:0" for="topic-note">My thinking</label><textarea id="topic-note" data-note="${section}-${esc(id)}" placeholder="Which scene best supports your interpretation?">${esc(state.notes[section+'-'+id]||'')}</textarea><span class="save-label">Saved in this browser.</span></div></aside></div>`;}
const evidence=[{quote:'told and not told',who:'Miss Lucy · Chapter 7',theme:'Knowledge & control',detail:'Miss Lucy challenges the gap between the students’ awareness of donation and their ability to comprehend their futures.',analysis:'The contradiction joins disclosure and concealment in one phrase. Hailsham can pass on information while keeping its emotional meaning at a distance. Connect this to jokes and evasions: the students also help maintain that distance.',use:'Argue that control depends on how knowledge is absorbed, as well as on what is hidden.',source:'https://www.litcharts.com/lit/never-let-me-go/quotes'},{quote:'We took away your art because we thought it would reveal your souls.',who:'Miss Emily · Chapter 22',theme:'Art & humanity',detail:'Miss Emily explains the purpose of the Gallery after Kathy and Tommy ask about a deferral.',analysis:'The possessive language gives the students inner lives, yet the adults still claim the right to collect and interpret them. Art becomes evidence judged by outsiders. The explanation exposes the unequal power to decide whose humanity counts.',use:'Connect Hailsham’s humane education to its failure to challenge the donation system itself.',source:'https://www.cardozohigh.com/ourpages/auto/2022/6/1/47025508/Title%20-%20Never%20Let%20Me%20Go.pdf'},{quote:'completion',who:'Institutional vocabulary · Throughout',theme:'Language & mortality',detail:'Deaths within the donation programme are described through the language of finishing a process.',analysis:'The euphemism makes an imposed death sound like the orderly fulfilment of a purpose. Kathy’s familiar use of institutional vocabulary reveals how deeply the system shapes everyday thought; her grief still communicates what that vocabulary conceals.',use:'Explain both the system’s dehumanising language and the narrator’s unmistakably human feelings.',source:'https://www.penguinrandomhouse.com/books/85609/never-let-me-go-by-kazuo-ishiguro/readers-guide'},{quote:'carer',who:'Kathy’s role · Introduced in Chapter 1',theme:'Care & complicity',detail:'Kathy takes pride in helping donors recover and endure their treatment.',analysis:'A familiar, compassionate word makes the opening feel reassuring before the larger system becomes clear. Kathy’s care is real and valuable, but it operates inside a structure that harms those she cares for. This tension resists a simple division into kindness and cruelty.',use:'Link the opening’s reassuring tone with the gradual disclosure of institutional violence.',source:'https://www.penguinrandomhouse.com/books/85609/never-let-me-go-by-kazuo-ishiguro/readers-guide'}];
function evidencePage(){return intro('Close reading','Small details. Strong arguments.','A compact quotation bank plus a wider scene bank. Learn how evidence works, then find the full passages in your own copy.')+`<div class="callout"><p><b>Use quotations precisely.</b> The wording in quotation marks below is quoted; scene descriptions elsewhere are paraphrases. Page numbers vary by edition. Add your own checked page references in your notes.</p></div><div class="grid two">${evidence.map(x=>`<article class="card evidence-card"><span class="eyebrow">${x.theme}</span><blockquote class="evidence-quote">“${esc(x.quote)}”</blockquote><p class="small-note">${x.who}</p><span class="label">Context</span><p>${esc(x.detail)}</p><span class="label">Method → meaning</span><p>${esc(x.analysis)}</p><span class="label">Build the argument</span><p>${esc(x.use)}</p><a class="source-ref" href="${x.source}" target="_blank" rel="noopener noreferrer">Text / reading reference ↗</a></article>`).join('')}</div><h2 style="margin:36px 0 20px">A scene for every major idea</h2><div class="grid two">${data.themes.map(t=>`<article class="card"><h3>${esc(t.title)}</h3>${list(t.evidence)}${link('themes/'+t.id,'Connect the evidence')}</article>`).join('')}</div>`;}
function flashDeck(){return flashOrder.map(id=>data.flashcards.find(x=>x.id===id)).filter(Boolean);}
function resetDeck(){flashOrder=data.flashcards.filter(x=>flashFilter==='All'||x.category===flashFilter).map(x=>x.id);flashIndex=0;flashFlipped=false;}
function flashcards(){if(!flashOrder.length)resetDeck();const deck=flashDeck(),c=deck[flashIndex%deck.length];return intro('Active recall','Remember it. Explain it.','Answer aloud before you turn the card. Mark a card as known only when you can explain the reasoning.')+`<section class="flashcard-area"><div class="toolbar"><label class="small-note">Deck <select id="flash-filter">${['All','Plot','Character','Theme','Method'].map(x=>`<option ${flashFilter===x?'selected':''}>${x}</option>`).join('')}</select></label><span class="counter">${flashIndex+1} / ${deck.length} · ${state.known.length} / ${data.flashcards.length} marked known</span>${button('shuffle','Shuffle','btn secondary small')}</div><article class="flashcard" tabindex="-1" aria-live="polite"><span class="eyebrow">${esc(c.category)} · ${flashFlipped?'The explanation':'The question'}${state.known.includes(c.id)?' · ✓ Known':''}</span>${flashFlipped?bi(c.back,data.flashcardZh?.[c.id]?.back):bi(c.front,data.flashcardZh?.[c.id]?.front,'h2')}${button('flip',flashFlipped?'Show question':'Reveal answer','btn secondary')}</article><div class="flashcard-actions">${button('flash-again','Study again','btn secondary')}${button('flash-known','I know this '+icon('check'),'btn')}</div><div class="toolbar">${button('flash-prev','← Previous','btn secondary small')}<span class="small-note">Your confidence markings stay in this browser.</span>${button('flash-next','Next →','btn secondary small')}</div></section>`;}
function quizPage(){if(quizDone){const score=quizAnswers.filter((x,i)=>x===data.quiz[i].correct).length;return intro('Retrieval practice','See what has stayed with you.','Use your mistakes to decide what to revise next.')+`<section class="quiz"><div class="card"><div class="eyebrow">Quiz complete</div><div class="score">${score}<span style="font-size:35px;color:var(--muted)"> / ${data.quiz.length}</span></div><p>Best result in this browser: ${state.best} / ${data.quiz.length}. ${score===data.quiz.length?'Now practise turning your knowledge into an argument.':'Review the explanations below, then revisit those ideas in the guide.'}</p><div class="toolbar">${button('quiz-restart','Try again')}${link('essays','Practise an essay')}</div></div><h2 style="margin:30px 0 20px">Review your answers</h2>${data.quiz.map((q,i)=>`<div class="card" style="margin-bottom:14px"><div class="eyebrow">${quizAnswers[i]===q.correct?'✓ Correct':'Review this'} · ${esc(q.category)}</div><h3 style="margin-top:10px">${esc(q.question)}</h3><p><b>Your answer:</b> ${esc(q.options[quizAnswers[i]])}</p><p><b>Correct answer:</b> ${esc(q.options[q.correct])}</p><p>${esc(q.explanation)}</p></div>`).join('')}</section>`;}const q=data.quiz[quizIndex],selected=quizAnswers[quizIndex],answered=selected!==undefined;return intro('Knowledge into confidence','Test yourself.','Twenty questions across the whole novel, with an explanation after every answer. No timer: think it through.')+`<section class="quiz"><div class="toolbar"><span class="eyebrow">Question ${quizIndex+1} of ${data.quiz.length}</span><span class="small-note">${esc(q.category)}</span></div><div class="progress-track"><span style="width:${quizIndex/data.quiz.length*100}%"></span></div><article class="quiz-question" tabindex="-1"><h2>${esc(q.question)}</h2><div class="quiz-options">${q.options.map((x,i)=>`<button class="quiz-option ${answered?(i===q.correct?'correct':i===selected?'incorrect':''):''}" data-action="quiz-answer" data-value="${i}" ${answered?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${esc(x)}${answered&&i===q.correct?' ✓':''}</button>`).join('')}</div>${answered?`<div class="callout" role="status"><h3>${selected===q.correct?'Correct.':'A useful one to revisit.'}</h3><p>${esc(q.explanation)}</p></div>${button('quiz-next',quizIndex===data.quiz.length-1?'See my results':'Next question '+icon('arrow'))}`:''}</article></section>`;}
let p1FilterChapter='all',p1FilterCategory='all',p1Count='all',p1Mode='practice',p1RouteChapter=null,p1ShowSetup=false;
function p1Pool(){return data.quizPart1.filter(q=>(p1FilterChapter==='all'||q.chapter===Number(p1FilterChapter))&&(p1FilterCategory==='all'||q.category===p1FilterCategory));}
function sanitizeP1Session(){const s=state.part1Session;if(!s||typeof s!=='object'||!Array.isArray(s.order)){state.part1Session=null;return;}const known=new Set(data.quizPart1.map(q=>q.id));s.order=[...new Set(s.order)].filter(id=>known.has(id));if(!s.order.length){state.part1Session=null;return;}const answers=s.answers&&typeof s.answers==='object'&&!Array.isArray(s.answers)?s.answers:{};s.answers=Object.fromEntries(Object.entries(answers).filter(([id,value])=>s.order.includes(id)&&Number.isInteger(value)&&value>=0&&value<4));s.index=Number.isInteger(s.index)?Math.min(Math.max(s.index,0),s.order.length-1):0;s.mode=s.mode==='exam'?'exam':'practice';s.complete=s.complete===true&&s.order.every(id=>s.answers[id]!==undefined);}
function p1Session(){const s=state.part1Session;if(!s||!Array.isArray(s.order)||!s.order.length)return null;return s;}
function p1Questions(s=p1Session()){return s?s.order.map(id=>data.quizPart1.find(q=>q.id===id)).filter(Boolean):[];}
function p1Start(questions){const pool=[...(questions||p1Pool())];for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}const take=questions?pool.length:p1Count==='all'?pool.length:Math.min(Number(p1Count),pool.length);if(!take){toast(words('Choose a different filter.','这个组合没有题目，请换一个筛选条件。'));return;}p1ShowSetup=false;state.part1Session={order:pool.slice(0,take).map(q=>q.id),answers:{},index:0,complete:false,mode:p1Mode};persist();renderPage();$('.quiz-question')?.focus({preventScroll:true});}
function p1Finish(){const s=p1Session(),qs=p1Questions();const missing=qs.findIndex(q=>s.answers[q.id]===undefined);if(missing>=0){s.index=missing;persist();renderPage();$('.quiz-question')?.focus({preventScroll:true});toast(words('Answer this question before submitting.','请先完成这一题，再提交测验。'));return;}s.complete=true;const score=qs.filter(q=>s.answers[q.id]===q.correct).length;state.part1Best=Math.max(state.part1Best||0,Math.round(score/qs.length*100));state.part1Last={score,total:qs.length,mode:s.mode};persist();renderPage();$('#p1-results')?.focus({preventScroll:true});}
function part1Quiz(routeChapter){
 if(routeChapter!==undefined&&routeChapter!==p1RouteChapter&&/^([1-9])$/.test(routeChapter)){p1FilterChapter=routeChapter;p1FilterCategory='all';p1RouteChapter=routeChapter;p1ShowSetup=true;}
 const s=p1Session(),qs=p1Questions(s),active=s&&!s.complete,showSession=!p1ShowSetup&&!!s&&qs.length===s.order.length;
 let head=intro('PART ONE · CHAPTERS 1–9',state.zh?'第一部 · 细节与理解测验':'The Chapters 1–9 quiz.',words('Names, objects, background and close reading. Verified against your supplied EPUB; no knowledge from Chapters 10–23 is needed.','不仅记住情节，也分清人物、物品和含义。题目已对照你提供的 EPUB；不需要第10–23章的知识。'));
 if(showSession&&s.complete){const wrong=qs.filter(q=>s.answers[q.id]!==q.correct),score=qs.length-wrong.length;return head+`<section id="p1-results" class="quiz" tabindex="-1"><div class="card"><div class="eyebrow">${words('Your result','本次结果')} · ${s.mode==='exam'?words('Test mode','测试模式'):words('Practice mode','练习模式')}</div><div class="score">${score}<span style="font-size:35px;color:var(--muted)"> / ${qs.length}</span></div>${bi('Review why each answer is right, especially when a name or object seemed almost familiar.','重点看清每个答案的依据，尤其是那些“看着眼熟”却容易混淆的人名和物品。')}<div class="toolbar">${wrong.length?button('p1-retry',words('Retry '+wrong.length+' missed questions','只重做 '+wrong.length+' 道错题')):''}${button('p1-new',words('Choose another set','选择新一组'),'btn secondary')}${link('part1-revision',words('Review the detail sheet','复习易错细节表'))}</div></div><h2 style="margin:30px 0 20px">${words('Answer review','逐题解析')}</h2>${qs.map((q,i)=>p1Review(q,s.answers[q.id],i)).join('')}</section>`;}
 if(showSession&&active){const q=qs[s.index],selected=s.answers[q.id],answered=selected!==undefined,reveal=answered&&s.mode==='practice';return head+`<section class="quiz"><div class="toolbar"><span class="eyebrow">${words('Question','第')} ${s.index+1} / ${qs.length}</span><span class="small-note">${s.mode==='exam'?words('Test · answers at the end','测试 · 最后统一解析'):words('Practice · instant explanation','练习 · 即时解析')} · ${esc(q.category)}</span></div><div class="progress-track"><span style="width:${Object.keys(s.answers).length/qs.length*100}%"></span></div><article class="quiz-question" tabindex="-1">${bi(q.question,q.questionZh,'h2')}<div class="quiz-options">${q.options.map((x,i)=>`<button class="quiz-option ${reveal?(i===q.correct?'correct':i===selected?'incorrect':''):i===selected?'selected':''}" data-action="p1-answer" data-value="${i}" aria-pressed="${i===selected}" ${reveal?'disabled':''}><span>${String.fromCharCode(65+i)}</span><div>${bi(x,q.optionsZh?.[i],'span')}</div>${reveal&&i===q.correct?'<b aria-label="Correct answer">✓</b>':''}</button>`).join('')}</div>${reveal?`<div class="callout" role="status" tabindex="-1"><h3>${selected===q.correct?words('Correct.','答对了。'):words('Look carefully at the distinction.','注意这个容易混淆的区别。')}</h3>${bi(q.explanation,q.explanationZh)}<p class="source-caption">${esc(q.locator)}</p>${q.chapter?link('chapters/'+q.chapter,words('Revisit this chapter','回看本章')):''}</div>`:''}<div class="toolbar">${button('p1-prev',words('← Previous','← 上一题'),'btn secondary',s.index===0?'disabled':'')}<span class="small-note">${Object.keys(s.answers).length} / ${qs.length} ${words('answered · saved locally','已回答 · 自动保存')}</span>${button('p1-next',s.index===qs.length-1?words('Submit & see results','提交并查看结果'):words('Next →','下一题 →'),'btn',s.mode==='practice'&&!answered?'disabled':'')}</div><div class="quiz-jump" aria-label="${words('Question navigator','题号导航')}">${qs.map((x,i)=>button('p1-jump',String(i+1),'question-dot '+(s.answers[x.id]!==undefined?'answered ':'')+(i===s.index?'current':''),`data-index="${i}" aria-label="${words('Question','第')}${i+1}${words('','题')}" ${i===s.index?'aria-current="step"':''}`)).join('')}</div><p class="small-note" style="margin-top:16px">${words('You can leave and return: this set and your answers stay in this browser.','可以先离开再回来：当前题组和答案会保存在此浏览器。')}</p>${button('p1-new',words('Leave this set & choose another','结束这组，重新选题'),'btn secondary small','style="margin-top:15px"')}</article></section>`;}
 const pool=p1Pool();return head+(s&&!s.complete&&p1ShowSetup?`<div class="callout">${bi('You have a saved set in progress. Resume it, or start a new set below to replace it.','你有一组尚未完成的题。可以继续原题组；点击下方开始按钮则会用新题组替换原进度。')}${button('p1-resume',words('Resume saved set','继续上次题组'),'btn secondary small')}</div>`:'')+`<div class="quiz-setup"><section class="card"><div class="eyebrow">${words('Build your practice set','选一组适合现在的题')}</div><h2>${words('Small details. Clear understanding.','记准细节，理解到位。')}</h2><div class="setup-fields"><label>${words('Chapter','章节范围')}<select id="p1-chapter"><option value="all">${words('All Chapters 1–9 + background','第1–9章 + 背景')}</option>${Array.from({length:10},(_,i)=>`<option value="${i}" ${p1FilterChapter===String(i)?'selected':''}>${i?words('Chapter '+i,'第'+i+'章'):words('Background only','仅背景知识')}</option>`).join('')}</select></label><label>${words('Question type','题目类型')}<select id="p1-category">${['all','Background','Names & details','Events','Interpretation'].map((x,i)=>`<option value="${x}" ${p1FilterCategory===x?'selected':''}>${state.zh?['全部类型','背景','人名与细节','情节','理解与分析'][i]:x==='all'?'All types':x}</option>`).join('')}</select></label><label>${words('Set length','题量')}<select id="p1-count">${['all','15','30'].map(x=>`<option value="${x}" ${p1Count===x?'selected':''}>${x==='all'?words('All matching questions','全部符合条件的题'):words(x+' questions',x+'题')}</option>`).join('')}</select></label><label>${words('Mode','模式')}<select id="p1-mode"><option value="practice" ${p1Mode==='practice'?'selected':''}>${words('Practice · instant feedback','练习 · 即时解析')}</option><option value="exam" ${p1Mode==='exam'?'selected':''}>${words('Test · reveal at the end','测试 · 最后统一解析')}</option></select></label></div><div class="callout">${bi('Practice mode explains each answer immediately. Test mode lets you revisit answers and reveals the explanations only after submission.','练习模式：每答一题就看解析。测试模式：可以回头修改答案，提交后才显示正确答案和解析。')}<p class="small-note">${pool.length} ${words('matching questions. Shorter pools use every matching question.','道符合条件的题。题目不足所选数量时，将使用全部符合条件的题。')}</p></div>${button('p1-start',words('Start this set '+icon('arrow'),'开始练习 '+icon('arrow')),'btn',pool.length?'':'disabled')}</section><aside><div class="card"><span class="eyebrow">${words('Before you begin','考前速查')}</span><h2 style="font-size:30px;margin-top:12px">${words('Bramble, Thunder… and Daffodil.','Bramble、Thunder，还有 Daffodil。')}</h2>${bi('Who rides which horse? Who starts the elbow prank? How are Exchanges different from Sales? Review the distinctions, then test yourself.','哪匹马先让 Kathy 骑？谁发起手肘拉链的玩笑？Exchanges 与 Sales 有什么区别？先分清，再自测。')}<div style="margin-top:20px">${link('part1-revision',words('Open the detail sheet','打开人物与细节速查表'),'btn secondary')}</div></div><div class="card" style="margin-top:20px"><h3>${words('Your latest result','最近一次成绩')}</h3><p>${state.part1Last?`${state.part1Last.score} / ${state.part1Last.total}`:words('No completed set yet.','还没有完成的测验。')}</p><p class="small-note">${words('Scores describe the set you chose; different set lengths are not directly comparable.','成绩对应你所选题组；不同题量、不同筛选条件的成绩不能直接比较。')}</p></div></aside></div>`;
}
function p1Review(q,selected,index){return `<article class="card p1-review"><div class="eyebrow">${index+1} · ${selected===q.correct?words('✓ Correct','✓ 答对'):words('Review this','需要复习')} · ${esc(q.locator)}</div>${bi(q.question,q.questionZh,'h3')}<p><b>${words('Your answer:','你的答案：')}</b> ${esc(q.options[selected])}${state.zh?' · '+esc(q.optionsZh?.[selected]||''):''}</p><p><b>${words('Correct answer:','正确答案：')}</b> ${esc(q.options[q.correct])}${state.zh?' · '+esc(q.optionsZh?.[q.correct]||''):''}</p>${bi(q.explanation,q.explanationZh)}${q.chapter?link('chapters/'+q.chapter,words('Review Chapter '+q.chapter,'复习第'+q.chapter+'章')):''}</article>`;}
function revisionPeople(title, rows, id){
 return `<section class="cram-section" id="${id}"><h2>${title}</h2><table class="names-table"><caption class="sr-only">${title}</caption><thead><tr><th scope="col">${words('Name','名字')}</th><th scope="col">${words('Connect the name to the incident','把名字和事件连起来记')}</th></tr></thead><tbody>${rows.map(x=>`<tr data-person="${esc([x.name,x.en,x.zh].join(' ').toLowerCase())}"><th scope="row">${esc(x.name)}<small>${esc(x.chapter)}</small></th><td>${bi(x.en,x.zh)}</td></tr>`).join('')}</tbody></table></section>`;
}
function part1Reference(){
 const c=data.part1Cram;
 const jumps=[['essentials','First priorities','先记重点'],['background','Dates & background','年份与背景'],['guardians','Guardians & adults','监护人与成人'],['students','Student names','学生名字'],['extra-students','More minor names','更多小人物'],['traps','Common traps','易混细节'],['details','Detail sheets','详细速查'],['recall','Cover & recall','遮住答案自测']];
 return `<div class="cram-notes">${intro('CHAPTERS 1–9 · QUIZ REVISION',words('The pre-quiz revision sheet.','考前复习笔记。'),words('Learn each name with its incident. Cover the answers, recall them, then use the quiz to find gaps. Story notes stay within Chapters 1–9.','把名字、身份和事件一起记。先读重点，再遮住答案自测，最后用选择题查漏补缺。情节范围仅第1–9章。'))}
 <div class="toolbar">${link('part1-quiz',words('Practise the 60 questions','练习60道专项题'),'btn')}${button('print',words('Print / save as PDF','打印 / 保存为PDF'),'btn secondary')}</div>
 <nav class="cram-jumps" aria-label="${words('Revision sections','复习笔记导航')}">${jumps.map(([id,en,cn])=>button('jump-section',words(en,cn),'filter',`data-target="cram-${id}"`)).join('')}</nav>
 <section id="cram-essentials" class="cram-section"><div class="section-heading"><div><span class="eyebrow">01 · ${words('Start here','先抓重点')}</span><h2>${words('If you only revise one list…','先把这份清单记牢。')}</h2></div></div><ol class="cram-priorities">${c.essentials.map(x=>`<li>${bi(x.en,x.zh)}</li>`).join('')}</ol></section>
 <section id="cram-background" class="cram-section"><span class="eyebrow">02 · ${words('Dates are different kinds of facts','分清不同的年份')}</span><h2>${words('Book facts & background','作品背景与年份')}</h2><div class="callout"><h3>${words('Published is not the same as written','published 与 written 要分清')}</h3>${bi(c.dateNote.en,c.dateNote.zh)}</div><div class="grid two">${c.background.map(x=>`<article class="card cram-fact"><h3>${esc(x.name)}</h3>${bi(x.en,x.zh)}${x.sourceId?sourceRefs([x.sourceId]):''}</article>`).join('')}</div></section>
 <div class="cram-name-tools"><label for="revision-name-search">${words('Find a guardian, student or incident','查找监护人、学生或相关事件')}</label><input id="revision-name-search" type="search" placeholder="${words('Try Christopher, Miss Lucy, calendar…','试试 Christopher、Miss Lucy、日历……')}"><p id="revision-name-status" role="status" class="small-note">${c.guardians.length+c.students.length+c.extraStudents.length} ${words('names to connect with scenes','个人名与场景对照')}</p></div>
 ${revisionPeople(words('Guardians, staff & the visitor','监护人、工作人员与来访者'),c.guardians,'cram-guardians')}
 ${revisionPeople(words('Students: the main three and the easily missed names','学生：主角与容易漏记的名字'),c.students,'cram-students')}
 ${revisionPeople(words('Extra names: a quick recognition list','更多小人物：认名字、认场景'),c.extraStudents,'cram-extra-students')}
 <section id="cram-traps" class="cram-section"><h2>${words('Do not swap these details','这些细节不要串在一起')}</h2><div class="grid two">${c.traps.map(x=>`<article class="card cram-fact"><h3>${esc(x.name)}</h3>${bi(x.en,x.zh)}<small class="small-note">${esc(x.chapter)}</small></article>`).join('')}</div></section>
 <section id="cram-details" class="cram-section"><h2>${words('Keep the object, the event and the meaning together','物品、情节与含义：详细速查')}</h2><div class="grid two">${data.part1Reference.map(x=>`<article class="card reference-card"><span class="eyebrow">${x.chapter?words('Chapter '+x.chapter,'第'+x.chapter+'章'):words('Background / reference','背景 / 综合')}</span><h3>${dualTitle(x.title,x.titleZh)}</h3>${x.facts.map(f=>`<div class="reference-fact">${bi(f.en,f.zh)}</div>`).join('')}${x.chapter?link('chapters/'+x.chapter,words('Read the chapter guide','阅读本章精讲')):''}</article>`).join('')}</div></section>
 <section id="cram-recall" class="cram-section"><h2>${words('Close the notes. Can you answer these?','合上笔记，你能答出来吗？')}</h2><p class="small-note">${words('Say the English name or term before opening each answer. These are recall prompts, not a prediction of your teacher’s questions.','先说出英文名字或术语，再展开答案。这是复习自测，不是对老师考题的预测。')}</p><div class="cram-recall">${c.recall.map((x,i)=>`<details><summary><span class="eyebrow">${String(i+1).padStart(2,'0')}</span> ${state.language==='chinese'?esc(x.qzh):esc(x.qen)}${state.language==='bilingual'?`<span class="recall-zh">${esc(x.qzh)}</span>`:''}</summary><div>${bi(x.aen,x.azh)}</div></details>`).join('')}</div></section>
 <div class="callout">${bi('For story details, the source is the supplied novel, Chapters 1–9. Dates and author facts link to the publisher and literary institutions. Interpretive points explain the evidence; they are not additional plot facts.','情节与姓名依据所提供小说第1–9章；出版年份与作者背景附出版方及文学机构链接。分析解释细节的含义，不要把推论写成小说已确认的事实。')}</div><div class="toolbar">${link('part1-quiz',words('Now test your recall','现在开始测验'),'btn')}${button('print',words('Print these notes','打印复习笔记'),'btn secondary')}</div></div>`;
}

function essays(){if(!essayId)essayId=data.essays[0].id;const e=data.essays.find(x=>x.id===essayId)||data.essays[0],draft=state.essays[e.id]||{};return intro('From evidence to argument','The essay workshop.','Practise a clear line of argument. These are original practice questions and examples, not official examination tasks or marked answers.')+`<div class="toolbar"><label class="field-label" style="margin:0">Choose a focus <select id="essay-select">${data.essays.map(x=>`<option value="${x.id}" ${x.id===e.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label>${button('export-essay','Download my draft','btn secondary small')}</div><div class="callout"><div class="eyebrow">Your question</div><h2 style="font-size:30px;margin-top:10px">${esc(e.question)}</h2></div>${state.zh&&data.essayZh?.[e.id]?`<section class="chinese-guide" lang="zh-CN"><div class="eyebrow">中文思路 · 先想清楚，再用英文论证</div>${data.essayZh[e.id].map(p=>`<p>${esc(p)}</p>`).join('')}</section>`:''}<div class="essay-layout"><article class="card reading"><div class="eyebrow">A worked approach</div><h2 style="margin-top:15px">Build a connected argument.</h2><details open><summary>A possible thesis</summary><p>${esc(e.thesis)}</p></details><details><summary>Explore a paragraph plan</summary>${e.plan.map((p,i)=>`<div class="analysis-box"><h3>${i+1}. ${esc(p.point)}</h3><span class="label">Evidence</span><p>${esc(p.evidence)}</p><span class="label">Analysis</span><p>${esc(p.analysis)}</p></div>`).join('')}</details><details><summary>Complicate your reading</summary><p>${esc(e.counterpoint)}</p></details><details><summary>Read a model paragraph</summary><p class="model">${esc(e.model)}</p><p class="small-note">Original model using scene references. Add a brief, accurately checked quotation from your edition when useful.</p></details><details><summary>Check your response</summary>${list(e.checklist)}</details></article><section class="card"><div class="eyebrow">Your writing space</div><h2 style="font-size:30px;margin-top:15px">Make it your own.</h2><p class="small-note" style="margin-top:8px">Try your own answer before opening the worked plan.</p>${[['thesis','My central argument','What is your overall answer to the question?'],['plan','My evidence & plan','Choose details from different parts. Explain how they develop or complicate your argument.'],['paragraph','My analytical paragraph','Detail → what it suggests → what it reveals about the novel’s wider concerns.']].map(([key,label,placeholder])=>`<label class="field-label" for="essay-${key}">${label}</label><textarea id="essay-${key}" data-essay="${e.id}" data-field="${key}" style="min-height:${key==='paragraph'?240:115}px" placeholder="${placeholder}">${esc(draft[key]||'')}</textarea>`).join('')}<span class="save-label">Saved automatically in this browser. Download a copy to keep it elsewhere.</span></section></div><div class="callout"><h3>A useful paragraph habit</h3><p>Make a claim → locate a precise detail → name and examine the method → explain the implication → connect it back to your argument. A technique label earns its place only when it helps you explain meaning.</p></div>`;}
function progress(){return intro('A manageable revision plan','A little progress, kept.','Work through these steps in any order. Your checklist records what you mark complete; it does not grade your understanding.')+`<div class="stats"><div class="stat"><strong>${state.chapters.length}<small style="font-size:16px">/23</small></strong><span>chapters<br>revised</span></div><div class="stat"><strong>${state.known.length}</strong><span>flashcards<br>known</span></div><div class="stat"><strong>${state.checks.length}<small style="font-size:16px">/${data.checklist.length}</small></strong><span>revision<br>steps</span></div><div class="stat"><strong>${state.best}</strong><span>best quiz<br>out of ${data.quiz.length}</span></div></div><div class="grid two"><section class="card"><h2 style="font-size:30px">Your revision checklist</h2>${data.checklist.map(c=>`<label class="checklist-row ${state.checks.includes(c.id)?'checked':''}"><input type="checkbox" data-check="${c.id}" ${state.checks.includes(c.id)?'checked':''}><span><b>${esc(c.label)}</b><small>${esc(c.description)}</small></span></label>`).join('')}</section><section><div class="card"><div class="eyebrow">A suggested route</div><h2 style="font-size:30px;margin-top:14px">Read. Retrieve. Connect. Write.</h2><p>Start with a chapter you find difficult. Explain its turning point without notes. Link that scene to a theme elsewhere in the novel. Use the connection to write one analytical paragraph.</p><div style="margin-top:20px">${link('chapters','Choose a chapter','btn')}</div></div><div class="card" style="margin-top:20px"><h3>Keep your work</h3><p>Notes, essay drafts, and progress are stored on this browser only. They are not synced across devices.</p><div class="toolbar">${button('export-progress','Export my notes','btn secondary small')}${button('print','Print checklist','btn secondary small')}</div><p class="small-note">${storageOK?'Local saving is available.':'Local saving is unavailable. Export your work before closing.'}</p></div></section></div>`;}
function sources(){return intro('Read with context','The novel, and the world around it.','Use context to illuminate a textual detail. Keep what the novel establishes separate from an interpretation of what it might mean.')+`<div class="timeline"><div><div class="eyebrow">Part one · Chapters 1–9</div><h3>Hailsham</h3><p>A protected childhood shaped by rules, art, friendship, and partial knowledge.</p></div><div><div class="eyebrow">Part two · Chapters 10–17</div><h3>The Cottages</h3><p>The transition to adulthood, where imitation and rumour offer imagined futures.</p></div><div><div class="eyebrow">Part three · Chapters 18–23</div><h3>Carers & donors</h3><p>Old relationships return as the limits of the system become unavoidable.</p></div></div><div class="grid two">${data.context.map(x=>`<article class="card"><h3>${esc(x.title)}</h3><p>${esc(x.explanation)}</p><p><b>Use carefully:</b> ${esc(x.caution)}</p></article>`).join('')}</div><h2 style="margin:38px 0 22px">A small critical vocabulary</h2><div class="grid two">${data.glossary.map(x=>`<article class="card"><h3>${esc(x.term)}</h3><p>${esc(x.definition)}</p><p><b>In this novel:</b> ${esc(x.application)}</p></article>`).join('')}</div><h2 style="margin:38px 0 15px">Reading & reference shelf</h2><p class="small-note">Original summaries, teaching notes, and interpretations are supported by the references below. Some external resources contain spoilers or require access. Chapter divisions refer to the novel, not the film.</p>${[...new Map(data.sources.map(s=>[s.url,s])).values()].map(s=>`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer"><b>${esc(s.title)}${s.id==='user-epub'?'':' ↗'}</b><p>${esc(s.note||'Reference for plot details and literary context.')}</p></a>`).join('')}<div class="callout"><h3>About this companion</h3><p>This is an independent revision resource, with original summaries and analysis rather than the novel’s full text. Read it alongside a lawful copy of Kazuo Ishiguro’s <i>Never Let Me Go</i>. Interpretations are arguments to test against the writing, not a single official answer. General IGCSE-style guidance is not tied to a particular exam-board mark scheme.</p></div>`;}
function notFound(){return intro('A page has gone astray','Let’s find your way back.','This section could not be found.')+link('overview','Return to the overview','btn');}
function renderPage(){const [section='overview',id]=location.hash.slice(1).split('/');if(section==='essays'&&id&&data.essays.some(x=>x.id===id))essayId=id;let html='';if(id&&section==='chapters')html=chapter(id);else if(id&&['characters','themes','methods'].includes(section))html=analysisDetail(section,id);else if(section==='overview'||!section)html=overview();else if(section==='chapters')html=chapters();else if(['characters','themes','methods'].includes(section))html=collection(section);else if(section==='evidence')html=evidencePage();else if(section==='flashcards')html=flashcards();else if(section==='part1-quiz')html=part1Quiz(id);else if(section==='part1-revision')html=part1Reference();else if(section==='quiz')html=quizPage();else if(section==='essays')html=essays();else if(section==='progress')html=progress();else if(section==='sources')html=sources();else html=notFound();$('#main').innerHTML=html+footer();document.title=`${nav.find(x=>x[0]===section)?.[2]||'Overview'} · Never Let Me Go`;}
function saveFile(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function moveFlash(n){flashIndex=(flashIndex+n+flashOrder.length)%flashOrder.length;flashFlipped=false;renderPage();$('.flashcard')?.focus({preventScroll:true});}
function searchEntries(){return [...['background','guardians','students','extraStudents','traps'].flatMap(k=>(data.part1Cram?.[k]||[]).map(x=>({label:x.name,kind:'Quiz revision notes',url:'part1-revision',text:JSON.stringify(x)}))),...data.chapters.map(x=>({label:`Chapter ${x.id} · ${x.title} ${x.titleZh||''}`,kind:'Chapter',url:'chapters/'+x.id,text:JSON.stringify(x)})),...['characters','themes','methods'].flatMap(type=>data[type].map(x=>({label:x.name||x.title,kind:type,url:type+'/'+x.id,text:JSON.stringify(x)+' '+(data.guides?.[type]?.[x.id]||[]).join(' ')}))),...data.part1Reference.map(x=>({label:x.title+' '+x.titleZh,kind:'Chapters 1–9 details',url:'part1-revision',text:JSON.stringify(x)})),...data.essays.map(x=>({label:x.title,kind:'Essay workshop',url:'essays/'+x.id,text:JSON.stringify(x)+' '+(data.essayZh?.[x.id]||[]).join(' ')})),...data.symbols.map(x=>({label:x.title,kind:'Symbol',url:'methods',text:JSON.stringify(x)})),...data.glossary.map(x=>({label:x.term,kind:'Glossary',url:'sources',text:JSON.stringify(x)})),...data.context.map(x=>({label:x.title,kind:'Context',url:'sources',text:JSON.stringify(x)}))];}
function updateSearch(q){q=q.trim().toLowerCase();const entries=q?searchEntries().filter(x=>(x.label+' '+x.text).toLowerCase().includes(q)).sort((a,b)=>Number(b.label.toLowerCase().includes(q))-Number(a.label.toLowerCase().includes(q))):[];$('.search-results').innerHTML=q?(entries.length?`<p class="small-note">${entries.length} result${entries.length===1?'':'s'}</p>`+entries.slice(0,35).map(x=>`<a class="search-result" href="#${x.url}"><span>${x.kind}</span><b>${esc(x.label)}</b></a>`).join(''):`<p class="empty">No results. Try a character, theme, or scene.</p>`):'<p class="small-note">Try memory, Madame, art, or deferrals.</p>';}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return;}if(e.target.closest('.search-result'))$('#search-dialog').close();const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='menu'){const open=$('#sidebar').classList.toggle('open');$('.menu-button').setAttribute('aria-expanded',String(open));}if(a==='search'){$('#search-dialog').showModal();$('#search-input').focus();}if(a==='close-search')$('#search-dialog').close();if(a==='part-filter'){chapterFilter=Number(b.dataset.value);renderPage();}if(a==='reveal'){const answer=b.parentElement.querySelector('.answer'),show=answer.classList.contains('hidden');answer.classList.toggle('hidden');b.textContent=show?words('Hide answer','收起答案'):words('Reveal a possible answer','查看参考答案');b.setAttribute('aria-expanded',String(show));}if(a==='chapter-done'){const id=Number(b.dataset.id);state.chapters=state.chapters.includes(id)?state.chapters.filter(x=>x!==id):[...state.chapters,id];persist();const y=scrollY;shell();scrollTo(0,y);}if(a==='jump-section'){const el=document.getElementById(b.dataset.target);el?.scrollIntoView({behavior:'smooth',block:'start'});el?.setAttribute('tabindex','-1');el?.focus({preventScroll:true});}if(a==='print')window.print();if(a==='flip'){flashFlipped=!flashFlipped;renderPage();$('[data-action="flip"]')?.focus({preventScroll:true});}if(a==='flash-next')moveFlash(1);if(a==='flash-prev')moveFlash(-1);if(a==='shuffle'){for(let i=flashOrder.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[flashOrder[i],flashOrder[j]]=[flashOrder[j],flashOrder[i]];}flashIndex=0;flashFlipped=false;renderPage();toast('Deck shuffled');}if(a==='flash-known'||a==='flash-again'){let id=flashOrder[flashIndex];state.known=state.known.filter(x=>x!==id);if(a==='flash-known')state.known.push(id);persist();moveFlash(1);}if(a==='quiz-answer'&&quizAnswers[quizIndex]===undefined){quizAnswers[quizIndex]=Number(b.dataset.value);renderPage();$('.callout[role="status"]')?.setAttribute('tabindex','-1');$('.callout[role="status"]')?.focus({preventScroll:true});}if(a==='quiz-next'){if(quizIndex===data.quiz.length-1){quizDone=true;state.best=Math.max(state.best,quizAnswers.filter((x,i)=>x===data.quiz[i].correct).length);persist();}else quizIndex++;renderPage();$('.quiz-question,.quiz')?.setAttribute('tabindex','-1');$('.quiz-question,.quiz')?.focus({preventScroll:true});}if(a.startsWith('p1-')){const s=p1Session(),qs=p1Questions(s);if(a==='p1-resume'){p1ShowSetup=false;renderPage();}if(a==='p1-start')p1Start();if(a==='p1-new'){p1ShowSetup=true;renderPage();}if(a==='p1-answer'&&s){const q=qs[s.index];if(s.mode==='exam'||s.answers[q.id]===undefined){s.answers[q.id]=Number(b.dataset.value);persist();renderPage();if(s.mode==='practice')$('.callout[role="status"]')?.focus({preventScroll:true});else document.querySelector('[data-action="p1-answer"][data-value="'+b.dataset.value+'"]')?.focus({preventScroll:true});}}if(a==='p1-prev'&&s){s.index=Math.max(0,s.index-1);persist();renderPage();$('.quiz-question')?.focus({preventScroll:true});}if(a==='p1-next'&&s){if(s.index===qs.length-1)p1Finish();else{s.index++;persist();renderPage();$('.quiz-question')?.focus({preventScroll:true});}}if(a==='p1-jump'&&s){s.index=Number(b.dataset.index);persist();renderPage();$('.quiz-question')?.focus({preventScroll:true});}if(a==='p1-retry'&&s){p1Mode='practice';p1Start(qs.filter(q=>s.answers[q.id]!==q.correct));}}if(a==='quiz-restart'){quizIndex=0;quizAnswers=[];quizDone=false;renderPage();}if(a==='export-progress'){saveFile('never-let-me-go-my-revision.json',JSON.stringify({exportedAt:new Date().toISOString(),...state},null,2),'application/json');toast('Notes and progress exported');}if(a==='export-essay'){const essay=data.essays.find(x=>x.id===essayId),draft=state.essays[essayId]||{};saveFile('never-let-me-go-essay.txt',`${essay.question}\n\nMY ARGUMENT\n${draft.thesis||''}\n\nMY PLAN\n${draft.plan||''}\n\nMY PARAGRAPH\n${draft.paragraph||''}`);toast('Draft downloaded');}});
document.addEventListener('change',e=>{const t=e.target;if(t.id.startsWith('p1-')){if(t.id==='p1-chapter'){p1FilterChapter=t.value;history.replaceState(null,'','#part1-quiz');p1RouteChapter=null;}if(t.id==='p1-category')p1FilterCategory=t.value;if(t.id==='p1-count')p1Count=t.value;if(t.id==='p1-mode')p1Mode=t.value;renderPage();document.getElementById(t.id)?.focus({preventScroll:true});}if(t.id==='language-select'){state.language=t.value;state.zh=t.value!=='english';persist();const y=scrollY;shell();scrollTo(0,y);$('#language-select').focus({preventScroll:true});}if(t.id==='flash-filter'){flashFilter=t.value;resetDeck();renderPage();$('#flash-filter').focus({preventScroll:true});}if(t.id==='essay-select'){essayId=t.value;history.replaceState(null,'','#essays/'+essayId);renderPage();$('#essay-select').focus({preventScroll:true});}if(t.dataset.check){let id=data.checklist.find(x=>String(x.id)===t.dataset.check)?.id;state.checks=state.checks.filter(x=>x!==id);if(t.checked)state.checks.push(id);persist();renderPage();document.querySelector('[data-check="'+id+'"]')?.focus({preventScroll:true});}});
document.addEventListener('input',e=>{if(e.target.id==='revision-name-search'){const q=e.target.value.trim().toLowerCase();let n=0;document.querySelectorAll('[data-person]').forEach(row=>{row.hidden=!row.dataset.person.includes(q);if(!row.hidden)n++;});$('#revision-name-status').textContent=n+' '+words('matching names','个匹配人名');}const t=e.target;if(t.id==='search-input')updateSearch(t.value);if(t.dataset.note){state.notes[t.dataset.note]=t.value;persist();}if(t.dataset.essay){state.essays[t.dataset.essay]??={};state.essays[t.dataset.essay][t.dataset.field]=t.value;persist();}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&!e.target.isContentEditable){e.preventDefault();$('#search-dialog').showModal();$('#search-input').focus();}});
window.addEventListener('hashchange',()=>{if(!location.hash.startsWith('#part1-quiz/'))p1RouteChapter=null;shell();scrollTo({top:0,behavior:'instant'});});
try{const responses=await Promise.all(['chapters','analysis','practice','part1','bilingual'].map(x=>fetch(`./data/${x}.json`).then(r=>{if(!r.ok)throw Error('Study content could not be loaded.');return r.json();})));data=Object.assign({},...responses);const sources=responses.flatMap(x=>x.sources||[]);sources.push({id:'novel-text',title:'Kazuo Ishiguro · Never Let Me Go (text reference)',url:'#sources',note:'Textual reference; chapter guides and the Part One quiz have been checked against the supplied EPUB.'},{id:'quotation-reference',title:'LitCharts · Selected quotations',url:evidence[0].source,note:'Reference for the Chapter 7 phrase and its speaker.'});data.sources=[...new Map(sources.map(x=>[x.id,x])).values()];sanitizeP1Session();resetDeck();shell();}catch(error){$('#app').innerHTML=`<div class="empty"><h1 style="font-size:38px">The room is not quite open.</h1><p style="margin:20px">${esc(error.message)} Please refresh to try again.</p><button class="btn" onclick="location.reload()">Try again</button></div>`;console.error(error);}
